#define PATTERN_SIZE 4
#define STRING_SIZE (16206)

void CPF(int pattern[PATTERN_SIZE], int kmpNext[PATTERN_SIZE]) {
  int k, q;
  k = 0;
  kmpNext[0] = 0;

c1:
  for (q = 1; q < PATTERN_SIZE; q++) {
  c2:
    while (k > 0 && pattern[k] != pattern[q]) {
      k = kmpNext[q];
    }
    if (pattern[k] == pattern[q]) {
      k++;
    }
    kmpNext[q] = k;
  }
}

void hls_top(int size, int xpattern[PATTERN_SIZE], int xinput[STRING_SIZE],
             int xkmpNext[PATTERN_SIZE], int xn_matches[1]) {
#pragma HLS INTERFACE m_axi port = xpattern
#pragma HLS INTERFACE m_axi port = xinput
#pragma HLS INTERFACE m_axi port = xkmpNext
#pragma HLS INTERFACE m_axi port = xn_matches
#pragma HLS INTERFACE s_axilite port = size
#pragma HLS INTERFACE s_axilite port = return
  int i, q, j;

  int pattern[PATTERN_SIZE];
  int input[STRING_SIZE];
  int kmpNext[PATTERN_SIZE];
  int n_matches[1];

  for (i = 0; i < PATTERN_SIZE; i++)
    pattern[i] = xpattern[i];
  for (i = 0; i < PATTERN_SIZE; i++)
    kmpNext[i] = xkmpNext[i];
  for (i = 0; i < size; i++)
    input[i] = xinput[i];

  n_matches[0] = 0;

  CPF(pattern, kmpNext);

  q = 0;
k1:
  for (i = 0; i < size; i++) {
  k2:
    j = 0;
    while (q > 0 && pattern[q] != input[i] && j < PATTERN_SIZE) {
      q = kmpNext[q];
      j++;
    }
    if (pattern[q] == input[i]) {
      q++;
    }
    if (q >= PATTERN_SIZE) {
      n_matches[0]++;
      q = kmpNext[q - 1];
    }
  }

  xn_matches[0] = n_matches[0];
}

